using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Threading.Tasks;using System.Drawing;using System.Windows.Forms;using V15Voice;
public static class WorkflowUi300Tests {
 static int count,code;static object F(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static object C(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,a);}static void Check(bool ok,string why){if(!ok)throw new Exception(why);count++;Console.WriteLine("PASS "+why);}
 static IEnumerable<Control> Walk(Control parent){foreach(Control c in parent.Controls){yield return c;foreach(var x in Walk(c))yield return x;}}
 static bool OnScreen(Control c){if(!c.Visible)return false;Rectangle r=c.RectangleToScreen(c.ClientRectangle);for(Control p=c.Parent;p!=null;p=p.Parent)if(!p.RectangleToScreen(p.ClientRectangle).Contains(r))return false;return true;}
 static void Capture(Form form,string name){Application.DoEvents();form.Refresh();using(var b=new Bitmap(form.Width,form.Height)){using(var g=Graphics.FromImage(b))g.CopyFromScreen(form.Location,Point.Empty,form.Size);b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"validation",name+".png"));}}
 static string FileSource(string root,string name){string dir=Path.Combine(root,name);Directory.CreateDirectory(dir);string path=Path.Combine(dir,name+".srt");File.WriteAllText(path,Scripts.ToSrt(new List<Cue>{new Cue{Id=1,Start=0,End=3.2,Text="The enormous bag he carried looked almost unreal."},new Cue{Id=2,Start=3.3,End=6.5,Text="This sentence remains exactly as supplied."}}));return path;}
 [STAThread]public static void Main(){Application.EnableVisualStyles();var form=new MainForm();form.Shown+=async(s,e)=>{try{
  var tabs=(TabControl)F(form,"tabs");var studio=(ComboBox)F(form,"workflowStudio");var batch=(ComboBox)F(form,"workflowBatch");var grid=(DataGridView)F(form,"grid");
  Check(form.Text.Contains("3.0.0")&&form.GetType().Assembly.GetName().Version.ToString()=="3.0.0.0","Actual WinForms executable reports version 3.0.0");Check(studio.Items.Count==2&&batch.Items.Count==2,"Studio and batch each expose exactly two workflow choices");Check(studio.SelectedIndex==0&&batch.SelectedIndex==0,"Clean installation starts in the non-rewriting file mode");
  studio.SelectedIndex=1;Check(batch.SelectedIndex==1&&((ComboBox)F(form,"aiMode")).SelectedIndex==2,"Selecting unattended AI in Studio also selects it for batch");batch.SelectedIndex=0;Check(studio.SelectedIndex==0&&((ComboBox)F(form,"aiMode")).SelectedIndex==0,"Selecting file-only batch mode also disables rewrite in Studio");
  Check(!grid.Columns.Contains("aiFix")&&(!((DataGridView)F(form,"jobGrid")).Columns.Contains("quickJob")||!((DataGridView)F(form,"jobGrid")).Columns["quickJob"].Visible),"Manual repair columns are removed from the normal workflow");
  string[] old={"AI nâng cao","A/B · sửa câu","SỬA NGAY","AI SỬA KHÁC","TỰ SỬA","CHẤP NHẬN","TIẾP TỤC RENDER","HOÀN TÁC"};Check(!Walk(form).OfType<Button>().Any(b=>old.Contains(b.Text)),"No redundant repair/approval/resume buttons remain on the app screens");Check(grid.Columns["text"].ReadOnly&&grid.Columns["start"].ReadOnly&&grid.Columns["end"].ReadOnly,"File preview cannot silently alter source words or timecodes");
  foreach(Size size in new[]{new Size(1440,960),new Size(1100,740)}){form.Size=size;form.Location=Point.Empty;Application.DoEvents();Check(OnScreen(studio)&&studio.Width>250&&OnScreen((Button)F(form,"render"))&&OnScreen((Button)F(form,"cancel"))&&OnScreen((Button)F(form,"openOutput")),"Mode selector and all three main actions fit at "+size);Check(OnScreen((ComboBox)F(form,"voices"))&&OnScreen((ComboBox)F(form,"family")),"Voice selectors remain visible at "+size);Capture(form,"workflow300-mode1-"+size.Width);}
  Check(!((Button)F(form,"globalCancel")).Visible,"The run screen contains one stop action, without a duplicate footer stop");
  C(form,"SetBusy",true);Check(!studio.Enabled&&!batch.Enabled&&((Button)F(form,"cancel")).Enabled,"Work locks both mode selectors and keeps stop available");C(form,"SetBusy",false);
  string root=Path.Combine(Path.GetTempPath(),"workflow300-ui "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string path=FileSource(root,"mode1");((ComboBox)F(form,"breathMode")).SelectedIndex=2;C(form,"LoadFile",path);string hash=StateFiles.Hash(path);
  // This real UI run intentionally has no installed engine/model. The failure
  // must finish through reports, with no modal repair or error dialog.
  await(Task)C(form,"RunWorkflowStudio");Check(Directory.GetFiles(Path.GetDirectoryName(path),"*.txt").Length==1,"Actual Studio failure in mode 1 writes exactly one report");Check(Application.OpenForms.Count==1&&!((bool)F(form,"busy")),"Failed automatic run returns without opening a modal dialog");Check(((Button)F(form,"openOutput")).Enabled&&File.Exists((string)F(form,"lastVoiceReport")),"Results remain accessible even when only an error report was produced");Check(StateFiles.Hash(path)==hash,"Actual UI run preserves original source bytes");
  path=FileSource(root,"mode2");C(form,"LoadFile",path);studio.SelectedIndex=1;form.Size=new Size(1440,960);form.Location=Point.Empty;Capture(form,"workflow300-ready-mode2-1440");form.Size=new Size(1100,740);Capture(form,"workflow300-ready-mode2-1100");await(Task)C(form,"RunWorkflowStudio");Check(Directory.GetFiles(Path.GetDirectoryName(path),"*.txt").Length==2,"Actual unattended Studio failure writes exactly the two selected reports");Check(Application.OpenForms.Count==1&&F(form,"quickRepairPanel")==null,"Unattended mode never opens or constructs a manual approval panel");Check(((Label)F(form,"workflowStudioHint")).Text.Contains("2 báo cáo"),"Mode 2 tells the user its exact report count");
  form.Size=new Size(1440,960);form.Location=Point.Empty;Capture(form,"workflow300-mode2-1440");form.Size=new Size(1100,740);Application.DoEvents();Capture(form,"workflow300-mode2-1100");
  var saved=(VoiceSettings)C(form,"CaptureSettings");Check(saved.WorkflowMode==2&&saved.AiMode==2,"Saved settings preserve the unattended mode without a review state");C(form,"Apply",new VoiceSettings{WorkflowMode=1,AiMode=1,Breathing=2});Check(studio.SelectedIndex==0&&batch.SelectedIndex==0&&((ComboBox)F(form,"aiMode")).SelectedIndex==0,"Applying a non-rewriting preset cannot leave the hidden AI setting enabled");
  string badDir=Path.Combine(root,"batch-bad");Directory.CreateDirectory(badDir);string bad=Path.Combine(badDir,"bad.srt");File.WriteAllText(bad,"invalid SRT");string good=FileSource(root,"batch-valid");C(form,"AddFiles",new object[]{new[]{bad,good}});batch.SelectedIndex=1;await(Task)C(form,"RunWorkflowBatch");Check(Directory.GetFiles(badDir,"*.txt").Length==2&&Directory.GetFiles(Path.GetDirectoryName(good),"*.txt").Length==2,"Batch creates exactly two reports for both an invalid input and a later engine failure");var jobs=(List<BatchJob>)F(form,"jobs");Check(jobs.Count==2&&jobs.All(j=>File.Exists(j.ReportPath)&&File.Exists(j.ShortReportPath)),"Every processed batch row exposes both existing report paths");Check(Application.OpenForms.Count==1&&!((CheckBox)F(form,"pauseBatchReview")).Visible,"Batch completes automatically with no pause-for-review control");
  Capture(form,"workflow300-batch-1100");tabs.SelectedIndex=0;((ComboBox)F(form,"voiceMode")).SelectedIndex=1;Check(((ComboBox)F(form,"secondVoice")).Visible&&grid.Columns["speaker"].Visible,"Existing two-voice routing remains available");Check(tabs.TabPages.Cast<TabPage>().Any(p=>p.Text.Contains("Sao chép giọng"))&&tabs.TabPages.Cast<TabPage>().Any(p=>p.Text.Contains("Thư viện giọng")),"Voice clone and voice library pages are retained");
  Console.WriteLine("TOTAL WORKFLOW UI300 "+count+" PASS. Real EXE under Mono/Xvfb, intentional missing-engine failures; no physical Windows/GPU or real TTS claim.");
 }catch(Exception error){Console.WriteLine(error);code=1;}finally{form.Close();}};Application.Run(form);Environment.Exit(code);}
}
